<script setup lang="ts">
import { onMounted, ref, computed, watch } from 'vue'; import { api, type Asset, type Row } from '../api'; import { number, iso, origins, methods, reasonLabel } from '../utils'; import AsyncPanel from '../components/AsyncPanel.vue'; import StatusBadge from '../components/StatusBadge.vue'; import JsonDetails from '../components/JsonDetails.vue'
const assets=ref<Asset[]>([]),selected=ref<string[]>([]),tasks=ref<Row[]>([]),economics=ref<Row[]>([]),task=ref(''),economy=ref('fp1_fn5'),origin=ref('local_operational'),method=ref('decay30'),at=ref(''),result=ref<Row|null>(null),loading=ref(false),error=ref('')
const assetDetails=ref<Record<string,Row>>({})
const reports=computed<Row[]>(()=>result.value?.reports??result.value?.valuations??[])
const comparison=computed(()=>result.value?.comparison?.comparison??result.value?.comparison??result.value?.result?.comparison??{})
onMounted(async()=>{try {const [a,t]=await Promise.all([api.assets(),api.tasks()]);assets.value=a;tasks.value=t.tasks??[];economics.value=t.economics??[];task.value=tasks.value.find(t=>t.task_id==='random_seed101_d01500_logistic')?.task_id??tasks.value[0]?.task_id??'';selected.value=['clean','label_020'].flatMap(id=>{const a=assets.value.find(x=>x.asset_id===id);return a?[a.asset_id+'|'+a.version]:[]})}catch(e){error.value=(e as Error).message}})
async function compare(){loading.value=true;error.value='';result.value=null;try {result.value=await api.compare({assets:selected.value.map(key=>{const [asset_id,version]=key.split('|');return{asset_id,version}}),task_id:task.value,economics_id:economy.value,origin:origin.value,method:method.value,at:iso(at.value)});const details=await Promise.all(selected.value.map(key=>{const [asset_id,version]=key.split('|');return api.detail({asset_id,version})}));assetDetails.value=Object.fromEntries(details.map(d=>[d.asset.asset_id,d]))}catch(e){error.value=(e as Error).message}finally{loading.value=false}}
watch([selected,task,economy,origin,method,at],()=>{result.value=null},{deep:true})
</script>
<template><section class="panel"><p class="eyebrow">COMPARISON WITH AN OUTSIDE OPTION</p><h2>比较相同任务与条件下的资产</h2><div class="asset-choices"><label v-for="a in assets" :key="a.asset_id+a.version" class="asset-choice" :class="{chosen:selected.includes(a.asset_id+'|'+a.version)}"><input v-model="selected" type="checkbox" :value="a.asset_id+'|'+a.version"><span><b>{{ a.asset_id }}</b><small>{{ a.provider_id }} · {{ a.version }}</small></span></label></div><div class="form-grid"><label>买方任务<select v-model="task" aria-label="对比买方任务"><option v-for="t in tasks" :key="t.task_id">{{ t.task_id }}</option></select></label><label>假设经济场景<select v-model="economy"><option v-for="e in economics" :key="e.economics_id??e.id" :value="e.economics_id??e.id">{{ e.economics_id??e.id }}</option></select></label><label>信用来源<select v-model="origin"><option v-for="o in origins" :key="o.value" :value="o.value" :disabled="o.value==='simulated'">{{ o.label }}{{ o.value==='simulated'?'（仅用于模拟统计，当前估值不支持）':'' }}</option></select></label><label>信用算法<select v-model="method"><option v-for="m in methods" :key="m.value" :value="m.value">{{ m.label }}</option></select></label><label>统一评估时点<input v-model="at" type="datetime-local"></label></div><div class="actions"><button class="button" :disabled="loading||selected.length<2||!task" @click="compare">比较研究价值</button><span class="muted small">所有候选共用同一任务、经济参数、来源与评估时点。</span></div></section><AsyncPanel :loading="loading" :error="error" @retry="compare"><template v-if="result"><section class="panel"><div class="panel-heading"><h2>条件价值对照</h2><StatusBadge :value="comparison.decision"/></div><div class="table-wrap"><table class="comparison-table"><thead><tr><th>维度</th><th v-for="r in reports" :key="r.asset_id">{{ r.asset_id }}<small>{{ r.asset_version??r.result?.version }}</small></th><th>不购买</th></tr></thead><tbody><tr><th>提供方与许可</th><td v-for="r in reports" :key="r.asset_id">{{ assetDetails[r.asset_id]?.asset?.provider_id ?? '—' }}<small>{{ assetDetails[r.asset_id]?.asset?.license ?? '—' }}</small></td><td>无新增许可</td></tr><tr><th>质量基线（描述用途）</th><td v-for="r in reports" :key="r.asset_id">{{ number(assetDetails[r.asset_id]?.quality?.quality_score,4) }}<small>{{ assetDetails[r.asset_id]?.quality ? '实际验收字节检测；不代表标签真实' : '暂无精确字节质量证据' }}</small></td><td>无新增资产</td></tr><tr><th>任务边际效用 ΔLog Loss</th><td v-for="r in reports" :key="r.asset_id">{{ number(r.conditional_utility?.result?.delta_utility??r.conditional_utility?.result?.delta_log_loss??r.conditional_utility?.result?.delta_logloss,6) }}</td><td>无新增任务数据</td></tr><tr><th>履约信用 q</th><td v-for="r in reports" :key="r.asset_id">{{ number(r.result?.q,4) }}<small>{{ r.result?.credit_n_history }} 份有效合同</small></td><td>不承担新增交付</td></tr><tr><th>成功条件收益</th><td v-for="r in reports" :key="r.asset_id">{{ number(r.result?.b_success) }}</td><td>0</td></tr><tr class="value-row"><th>风险调整 W</th><td v-for="r in reports" :key="r.asset_id" :class="{'text-danger':r.result?.value<=0}">{{ number(r.result?.value) }}</td><td>0<small>相对不交易基准</small></td></tr><tr><th>固定 q 任务区间</th><td v-for="r in reports" :key="r.asset_id">[{{ number(r.result?.conditional_low) }}, {{ number(r.result?.conditional_high) }}]</td><td>不适用</td></tr><tr><th>测量 / 模型状态</th><td v-for="r in reports" :key="r.asset_id"><StatusBadge :value="r.status"/><small>{{ r.result?.model_status??r.reason }}</small></td><td>合理决策选项</td></tr><tr><th>研究建议限制</th><td v-for="r in reports" :key="r.asset_id"><ul class="compact-list"><li v-for="reason in (r.result?.reasons??[r.reason]).filter(Boolean)" :key="reason">{{ reasonLabel(reason) }}</li></ul></td><td>候选不可用、负收益或证据不足时保留</td></tr></tbody></table></div><div class="notice warning">负收益保留原值。条件价值排序不能替代证据、授权与不确定性判断；不构成正式商业采购建议。</div><JsonDetails :data="comparison" title="核对研究决策、排除原因和不购买选项"/></section><section v-for="r in reports" :key="r.asset_id" class="panel"><h3>{{ r.asset_id }} · 来源、质量与完整依据</h3><p class="muted small">{{ assetDetails[r.asset_id]?.asset?.provenance?.source ?? assetDetails[r.asset_id]?.asset?.source }}</p><JsonDetails :data="assetDetails[r.asset_id]" title="精确版本元数据、SHA-256 与实际质量"/><JsonDetails :data="r" title="展开资产报告（包含测量来源、区间与证据）"/></section><JsonDetails :data="result" title="核对完整比较 API 响应"/></template><section v-else class="panel empty-intro"><span>⇌</span><h3>正收益不是唯一标准</h3><p>质量、履约信用和任务效用是不同维度；不购买始终是可解释的外部选项。</p></section></AsyncPanel></template>
